import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"前瞻基建相关信息","description":"","frontmatter":{"translationSource":{"title":"前瞻基建相关信息","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fsJYZfKeanEF8by8G17JcB","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-7-factory-preview-information"}]]},"headers":[],"relativePath":"zh/1-7-factory-preview-information.md","filePath":"zh/page-fsJYZfKeanEF8by8G17JcB.md"}'),d={name:"zh/1-7-factory-preview-information.md"};function c(o,e,r,p,l,n){return s(),t("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><h1 id="前瞻基建相关信息" tabindex="-1">前瞻基建相关信息 <a class="header-anchor" href="#前瞻基建相关信息" aria-label="Permalink to &quot;前瞻基建相关信息&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>fsJYZfKeanEF8by8G17JcB</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fsJYZfKeanEF8by8G17JcB" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8d6f57dd8dbf001d.q90-8467606bc6e699dc.webp" alt="前瞻基建相关信息"></p><p>提交产物a，b，c</p><p>铜封明壤元件+铜封重装组件+辉铜能量块</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a5019e76007be08e.q90-7a4ff20d69b60508.webp" alt="前瞻基建相关信息"></p><p>15（？）晦铜零件+2重息壤=1提交产物b（封装机10s）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9ff39b86862ea120.q90-3b5f092a0da125fc.webp" alt="前瞻基建相关信息"></p><p>10明铜零件+5明息壤=1提交产物a（封装机10s）（基本确定）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b3f0a85b16bcf80d.q90-8c501d5d38b68bd0.webp" alt="前瞻基建相关信息"></p><p>10衡铜零件+10致密原石粉末=1提交产物C（封装机10s）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-36c58912ef222ece.q90-3bf147eff80d2d42.webp" alt="前瞻基建相关信息"></p><p>地区是65*65大小（可能还没升满？）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7e621d3c2b1c1cf8.q90-3379968e973aa409.webp" alt="前瞻基建相关信息"></p><p>4个区域重叠是100%变化概率，明晦炉能给1个区域，分影明晦炉能给2个区域（90度相邻），6息壤气激活</p><p>疑似：明晦炉的数量有限，至少14个<br> 平衡炉可能涉及的配方：明息壤+晦息壤=重息壤（基本确定，具体的产量未知） 10s一次产两个</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c946f975f91dcb7a.q90-d71482d688f4fcec.webp" alt="前瞻基建相关信息"></p><p>第五次天有烘炉扩容，推测是加5个（可能是4，6，8？）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-82ff1383b12894d5.q90-98338ab8dc38250c.webp" alt="前瞻基建相关信息"></p><p>推测：明晦炉、重建供应端口、解锁晦区域、平衡炉、解锁衡区域、分影明晦炉</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c32612bd6f4cf7ec.q90-565cde4c45a5e30e.webp" alt="前瞻基建相关信息"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-311cfcd3df6e549c.q90-f287730f08322728.webp" alt="前瞻基建相关信息"></p><p>普通明晦炉的作用范围（万一有人用呢）</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-96e72320c00ef57d.q90-78aba4a652b8817c.webp" alt="前瞻基建相关信息"></p><p>分影明晦炉的作用范围：上方输入息壤气，右侧和下侧产生区域</p><p><span id="source-block-3MpyPySCSGgJWLdaFgCXB5"></span></p><h2 id="新设备、新产物、新配方" tabindex="-1">新设备、新产物、新配方： <a class="header-anchor" href="#新设备、新产物、新配方" aria-label="Permalink to &quot;新设备、新产物、新配方：&quot;">​</a></h2><p><span id="source-block-nKwi1jcOMD9o6nQxDVm9JJ"></span></p><h2 id="泄露产线截图" tabindex="-1">泄露产线截图： <a class="header-anchor" href="#泄露产线截图" aria-label="Permalink to &quot;泄露产线截图：&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td></td></tr></tbody></table><blockquote><p>数据表（共 1 条）：公开访客会话未能读取记录内容，需登录腾讯文档后查看。</p></blockquote><p><span id="source-block-wNkadqrBiCvuYL7brm0iva"></span></p><h2 id="泄露产线平面蓝图" tabindex="-1">泄露产线平面蓝图： <a class="header-anchor" href="#泄露产线平面蓝图" aria-label="Permalink to &quot;泄露产线平面蓝图：&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td></td></tr></tbody></table><blockquote><p>数据表（共 1 条）：公开访客会话未能读取记录内容，需登录腾讯文档后查看。</p></blockquote><p><span id="source-block-B2I8uzZu7IKpVVVtbYM1g7"></span></p><h2 id="配方推测" tabindex="-1">配方推测： <a class="header-anchor" href="#配方推测" aria-label="Permalink to &quot;配方推测：&quot;">​</a></h2><p><span id="source-block-XiwVHHvXAMpB7pxXnx2anJ"></span></p><h2 id="配方分析" tabindex="-1">配方分析： <a class="header-anchor" href="#配方分析" aria-label="Permalink to &quot;配方分析：&quot;">​</a></h2></div>',1)])])}const h=a(d,[["render",c]]);export{b as __pageData,h as default};
